def simulate(w):
    state = 'q0'
    for ch in w:
        if state == 'q0':
            state = 'q1' if ch == '0' else 'q0'
        elif state == 'q1':
            state = 'q1' if ch == '0' else 'q2'
        else:  # state == 'q2'
            state = 'q1' if ch == '0' else 'q0'
    return 'Accepted' if state == 'q2' else 'Rejected'

if __name__ == "__main__":
    test = "11001"
    print(simulate(test))
